/**
 * The weekly send of the Monday sheet (v2.5883): the switch, the tick, the record of the last run, who hears it and
 * the words the Bridge's card and the function share. Pure. The function `bridge-weekly-sheet` reads the switch,
 * the tick and the recipients from the copy of the kernels; `weeklySendIo.ts` reads and writes the switch for the
 * page.
 *
 * The switch is `app_settings` `bridge_weekly_sheet_on_v1`, 'false' as it ships (migration `bridge_weekly_sheet`);
 * only a dev may change it. The cron fires at 11:00 and 12:00 UTC on Mondays and posts only while the switch is on;
 * one tick is 6 AM Central in summer, the other in winter, and the function runs only the tick that is 6 AM. The
 * last run is `bridge_weekly_sheet_last_run_v1`, written by the function, so the card says when the sheet last went
 * and to how many people, and a second tick the same day sends nothing twice.
 */
import { APP_CALENDAR_TZ } from '../../utils/dateUtils.ts'

export const WEEKLY_SHEET_ON_KEY = 'bridge_weekly_sheet_on_v1'
export const WEEKLY_SHEET_LAST_RUN_KEY = 'bridge_weekly_sheet_last_run_v1'
/** The run's hour in the app's zone: early Monday, before the owner reads mail. */
export const WEEKLY_SEND_HOUR = 6
/** Mondays at 11:00 and 12:00 UTC: 6 AM Central in summer and in winter. */
export const WEEKLY_SEND_CRON = '0 11,12 * * 1'

/** Whether the switch reads on: only 'true' lets the cron post, as its statement and the function read it. */
export function weeklySheetIsOn(valueText: string | null | undefined): boolean {
  return valueText === 'true'
}

/** Whether this tick is the send's hour: a Monday, 6 AM Central. */
export function weeklySendTickNow(now: Date): boolean {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: APP_CALENDAR_TZ, weekday: 'short', hour: '2-digit', hourCycle: 'h23' }).formatToParts(now)
  const get = (t: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === t)?.value ?? ''
  return get('weekday') === 'Mon' && Number(get('hour')) % 24 === WEEKLY_SEND_HOUR
}

/** The run as the function keeps it. */
export interface WeeklySendRun {
  /** When it ran, an ISO timestamp. */
  at: string
  /** The company-calendar day it ran on. */
  day: string
  /** A dry run built the sheet and sent nothing. */
  dry: boolean
  /** The addresses the sheet went to. */
  sent: string[]
  /** The addresses it did not reach, each with the sender's words. */
  failed: Array<{ to: string; error: string }>
  /** What could not be read when the sheet was built. */
  gaps: string[]
  subject: string
}

/** The row's text as a run, or null when it is empty or not a run. */
export function parseWeeklySendRun(valueText: string | null | undefined): WeeklySendRun | null {
  if (!valueText) return null
  try {
    const v = JSON.parse(valueText) as Partial<WeeklySendRun> | null
    if (!v || typeof v !== 'object' || typeof v.at !== 'string' || typeof v.day !== 'string') return null
    return {
      at: v.at,
      day: v.day,
      dry: v.dry === true,
      sent: Array.isArray(v.sent) ? v.sent.filter((s): s is string => typeof s === 'string') : [],
      failed: Array.isArray(v.failed) ? v.failed.filter((f): f is { to: string; error: string } => !!f && typeof f === 'object' && typeof (f as { to?: unknown }).to === 'string') : [],
      gaps: Array.isArray(v.gaps) ? v.gaps.filter((g): g is string => typeof g === 'string') : [],
      subject: typeof v.subject === 'string' ? v.subject : '',
    }
  } catch {
    return null
  }
}

/** A second tick the same day sends nothing twice: the sheet went today already. */
export function alreadySentToday(run: WeeklySendRun | null, todayYmd: string): boolean {
  return !!run && !run.dry && run.day === todayYmd && run.sent.length > 0
}

export interface RecipientRow {
  role: string | null
  email: string | null
  archived_at: string | null
  is_sample?: boolean | null
  is_digital_twin?: boolean | null
  is_walk_tester?: boolean | null
}

/** Every dev with a real account and an address, each once, in the order read: never anyone else. */
export function weeklySendRecipients(rows: ReadonlyArray<RecipientRow>): string[] {
  const out: string[] = []
  for (const r of rows) {
    if (r.role !== 'dev' || r.archived_at || r.is_sample || r.is_digital_twin || r.is_walk_tester) continue
    const email = (r.email ?? '').trim().toLowerCase()
    if (!email || out.includes(email)) continue
    out.push(email)
  }
  return out
}

