/** The line under the switch: what happens while it is on, or that nothing does while it is off. */
export function weeklySendStateWords(on: boolean): string {
  return on ? 'On: the sheet goes to every dev on Monday at 6 AM Central.' : 'Off: nothing goes out on Monday. Email me this sheet still works.'
}

/** "Last sent Oct 27 to 2 people", with what failed and what was not read. */
export function lastRunWords(run: WeeklySendRun | null, dayLabel: (ymd: string) => string): string {
  if (!run) return 'Not sent yet.'
  const n = run.sent.length
  const people = `${n} ${n === 1 ? 'person' : 'people'}`
  const head = run.dry ? `Last dry run ${dayLabel(run.day)}, built for ${people}` : n > 0 ? `Last sent ${dayLabel(run.day)} to ${people}` : `Last run ${dayLabel(run.day)} sent to nobody`
  const failed = run.failed.length ? `. ${run.failed.length} ${run.failed.length === 1 ? 'address' : 'addresses'} failed` : ''
  const gaps = run.gaps.length ? `. Not read: ${run.gaps.join(', ')}` : ''
  return `${head}${failed}${gaps}.`
}
